package com.enterpriseflow.service;
import com.enterpriseflow.entity.*; import com.enterpriseflow.repository.*; import com.enterpriseflow.workspace.dto.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class WorkspaceService { private final ProjectRepository projects; private final TaskRepository tasks; private final TaskCommentRepository comments; private final UserRepository users; private final NotificationRepository notifications; private final ActivityLogRepository activities;
 public WorkspaceService(ProjectRepository p,TaskRepository t,TaskCommentRepository c,UserRepository u,NotificationRepository n,ActivityLogRepository a){projects=p;tasks=t;comments=c;users=u;notifications=n;activities=a;}
 private User user(String email){User u=users.findByEmail(email).orElseThrow();if(u.getMembershipStatus()!=MembershipStatus.ACTIVE||u.getCompany()==null)throw new AccessDeniedException("Your company access is " + u.getMembershipStatus().name().toLowerCase() + ".");return u;} private Project project(UUID id){return projects.findById(id).orElseThrow(()->new NoSuchElementException("Project not found."));} private Task task(UUID id){return tasks.findById(id).orElseThrow(()->new NoSuchElementException("Task not found."));} private boolean admin(User u){return u.getRole()==UserRole.ADMIN;} private void access(Project p,User u){if(!p.getCompany().getId().equals(u.getCompany().getId()))throw new AccessDeniedException("You do not have access to this project.");if(!admin(u)&&!p.hasMember(u.getId()))throw new AccessDeniedException("You do not have access to this project.");} private void owner(Project p,User u){access(p,u);if(!admin(u)&&!p.getOwner().getId().equals(u.getId()))throw new AccessDeniedException("Only a project owner or administrator can do that.");} private void adminOnly(User u){if(!admin(u))throw new AccessDeniedException("Administrator access is required.");}
 @Transactional public Map<String,Object> createProject(String email,ProjectRequest r){User u=user(email);adminOnly(u);Project p=projects.save(new Project(r.name().trim(),r.description(),u,r.dueDate()));p.update(p.getName(),p.getDescription(),r.status()==null?"PLANNING":r.status(),r.dueDate());activities.save(new ActivityLog(u,"CREATED","PROJECT",p.getId(),"Created project "+p.getName()));return projectView(p);}
 @Transactional(readOnly=true) public List<Map<String,Object>> listProjects(String email){User u=user(email);List<Project> visible=admin(u)?projects.findActiveByCompanyId(u.getCompany().getId()):projects.findVisibleByCompanyIdAndUserId(u.getCompany().getId(),u.getId());return visible.stream().map(this::projectView).toList();}
 @Transactional(readOnly=true) public Map<String,Object> getProject(String email,UUID id){Project p=project(id);access(p,user(email));return projectView(p);}
 @Transactional public Map<String,Object> updateProject(String email,UUID id,ProjectRequest r){User u=user(email);Project p=project(id);owner(p,u);p.update(r.name().trim(),r.description(),r.status()==null?p.getStatus():r.status(),r.dueDate());activities.save(new ActivityLog(u,"UPDATED","PROJECT",id,"Updated project "+p.getName()));return projectView(p);}
 @Transactional public void archiveProject(String email,UUID id){User u=user(email);Project p=project(id);owner(p,u);p.archive();activities.save(new ActivityLog(u,"ARCHIVED","PROJECT",id,"Archived project "+p.getName()));}
 @Transactional public Map<String,Object> addMember(String email,UUID id,UUID memberId){User u=user(email);adminOnly(u);Project p=project(id);access(p,u);User member=users.findById(memberId).orElseThrow();if(member.getMembershipStatus()!=MembershipStatus.ACTIVE||member.getCompany()==null||!member.getCompany().getId().equals(u.getCompany().getId()))throw new IllegalArgumentException("Only approved members of this company can be added.");if(p.addMember(member)){projects.saveAndFlush(p);notifications.save(new Notification(member,"Project assigned","You were added to project: "+p.getName(),"PROJECT_ASSIGNMENT"));}return projectView(p);}
 @Transactional public Map<String,Object> createTask(String email,UUID projectId,TaskRequest r){User u=user(email);adminOnly(u);Project p=project(projectId);access(p,u);User assignee=r.assigneeId()==null?null:users.findById(r.assigneeId()).orElseThrow();if(assignee!=null&&(assignee.getCompany()==null||!assignee.getCompany().getId().equals(u.getCompany().getId())||assignee.getMembershipStatus()!=MembershipStatus.ACTIVE||!p.hasMember(assignee.getId())))throw new IllegalArgumentException("Assignee must be an approved project member.");Task t=tasks.save(new Task(p,r.title().trim(),r.description(),r.priority()==null?"MEDIUM":r.priority(),assignee,u,r.dueDate()));if(r.status()!=null)t.update(t.getTitle(),t.getDescription(),r.status(),t.getPriority(),assignee,r.dueDate());activities.save(new ActivityLog(u,"CREATED","TASK",t.getId(),"Created task "+t.getTitle()));if(assignee!=null&&!assignee.getId().equals(u.getId()))notifications.save(new Notification(assignee,"Task assigned","You were assigned: "+t.getTitle(),"TASK_ASSIGNMENT"));return taskView(t);}
 @Transactional(readOnly=true) public List<Map<String,Object>> listTasks(String email,UUID projectId,String status,String priority){User u=user(email);Project p=project(projectId);access(p,u);return tasks.findByProjectId(projectId).stream().filter(t->status==null||status.equals(t.getStatus())).filter(t->priority==null||priority.equals(t.getPriority())).map(this::taskView).toList();}
 @Transactional public Map<String,Object> updateTask(String email,UUID id,TaskRequest r){User u=user(email);Task t=task(id);access(t.getProject(),u);if(!admin(u)&&(t.getAssignee()==null||!t.getAssignee().getId().equals(u.getId())))throw new AccessDeniedException("Only the assignee or an administrator can update this task.");User previous=t.getAssignee();User a=admin(u)?(r.assigneeId()==null?null:users.findById(r.assigneeId()).orElseThrow()):previous;if(a!=null&&(a.getCompany()==null||!a.getCompany().getId().equals(u.getCompany().getId())||a.getMembershipStatus()!=MembershipStatus.ACTIVE||!t.getProject().hasMember(a.getId())))throw new IllegalArgumentException("Assignee must be an approved project member.");t.update(admin(u)?r.title().trim():t.getTitle(),admin(u)?r.description():t.getDescription(),r.status()==null?t.getStatus():r.status(),admin(u)?(r.priority()==null?t.getPriority():r.priority()):t.getPriority(),a,admin(u)?r.dueDate():t.getDueDate());tasks.save(t);if(a!=null&&(previous==null||!previous.getId().equals(a.getId()))&&!a.getId().equals(u.getId()))notifications.save(new Notification(a,"Task assigned","You were assigned: "+t.getTitle(),"TASK_ASSIGNMENT"));activities.save(new ActivityLog(u,"UPDATED","TASK",id,"Updated task "+t.getTitle()));return taskView(t);}
 @Transactional public void deleteTask(String email,UUID id){User u=user(email);Task t=task(id);owner(t.getProject(),u);tasks.delete(t);activities.save(new ActivityLog(u,"DELETED","TASK",id,"Deleted task"));}
 @Transactional public Map<String,Object> comment(String email,UUID id,String content){User u=user(email);Task t=task(id);access(t.getProject(),u);TaskComment c=comments.save(new TaskComment(t,u,content.trim()));activities.save(new ActivityLog(u,"COMMENTED","TASK",id,"Commented on "+t.getTitle()));return Map.of("id",c.getId(),"content",c.getContent(),"author",c.getAuthor().getName(),"createdAt",c.getCreatedAt());}
 @Transactional(readOnly=true) public List<Map<String,Object>> comments(String email,UUID id){Task t=task(id);access(t.getProject(),user(email));return comments.findByTaskIdOrderByCreatedAtAsc(id).stream().map(c->Map.<String,Object>of("id",c.getId(),"content",c.getContent(),"author",c.getAuthor().getName(),"createdAt",c.getCreatedAt())).toList();}
 @Transactional(readOnly=true) public Map<String,Object> dashboard(String email){User u=user(email);List<Map<String,Object>> ps=listProjects(email);List<Task> mine=tasks.findByAssigneeIdAndProjectCompanyId(u.getId(),u.getCompany().getId());return Map.of("projects",ps.size(),"projectItems",ps,"myTasks",mine.size(),"myTaskItems",mine.stream().map(this::taskView).toList(),"overdue",mine.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(LocalDate.now())&&!("DONE".equals(t.getStatus()))).count(),"unreadNotifications",notifications.countByRecipientIdAndReadFalse(u.getId()),"recentActivity",activities.findTop20ByActorIdOrderByCreatedAtDesc(u.getId()).stream().map(this::activityView).toList());}
 @Transactional(readOnly=true) public Map<String,Object> analytics(String email){User actor=user(email);UUID companyId=actor.getCompany().getId();boolean admin=admin(actor);List<Map<String,Object>> projectViews=listProjects(email);Set<UUID> ids=projectViews.stream().map(x->(UUID)x.get("id")).collect(java.util.stream.Collectors.toSet());List<Project> visibleProjects=projects.findAllById(ids);List<Task> visible=(admin?tasks.findByProjectCompanyId(companyId):tasks.findByAssigneeIdAndProjectCompanyId(actor.getId(),companyId)).stream().filter(t->ids.contains(t.getProject().getId())).toList();LocalDate today=LocalDate.now(),through=today.plusDays(7);List<Task> completed=visible.stream().filter(t->"DONE".equalsIgnoreCase(t.getStatus())).toList();List<Task> overdue=visible.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(today)&&!"DONE".equalsIgnoreCase(t.getStatus())).toList();List<Task> pending=visible.stream().filter(t->!"DONE".equalsIgnoreCase(t.getStatus())).toList();List<Project> delayed=visibleProjects.stream().filter(p->p.getDueDate()!=null&&p.getDueDate().isBefore(today)&&!"COMPLETED".equalsIgnoreCase(p.getStatus())).toList();List<Map<String,Object>> deadlines=new ArrayList<>();for(Task t:visible)if(t.getDueDate()!=null&&!t.getDueDate().isBefore(today)&&!t.getDueDate().isAfter(through)&&!"DONE".equalsIgnoreCase(t.getStatus()))deadlines.add(Map.of("id",t.getId(),"kind","TASK","title",t.getTitle(),"project",t.getProject().getName(),"dueDate",t.getDueDate().toString(),"assignee",t.getAssignee()==null?"Unassigned":t.getAssignee().getName()));for(Project p:visibleProjects)if(p.getDueDate()!=null&&!p.getDueDate().isBefore(today)&&!p.getDueDate().isAfter(through)&&!"COMPLETED".equalsIgnoreCase(p.getStatus()))deadlines.add(Map.of("id",p.getId(),"kind","PROJECT","title",p.getName(),"project",p.getName(),"dueDate",p.getDueDate().toString(),"assignee",""));deadlines.sort(Comparator.comparing(x->LocalDate.parse((String)x.get("dueDate"))));List<Map<String,Object>> progress=visibleProjects.stream().map(p->{List<Task> pt=visible.stream().filter(t->t.getProject().getId().equals(p.getId())).toList();long done=pt.stream().filter(t->"DONE".equalsIgnoreCase(t.getStatus())).count();Map<String,Object>x=new LinkedHashMap<>();x.put("id",p.getId());x.put("name",p.getName());x.put("status",p.getStatus());x.put("dueDate",p.getDueDate()==null?"":p.getDueDate().toString());x.put("taskCount",pt.size());x.put("completedTasks",done);x.put("completionPercent",pt.isEmpty()?0:Math.round(done*100.0/pt.size()));return x;}).toList();Map<String,Object> result=new LinkedHashMap<>();result.put("companyWide",admin);result.put("projectCount",ids.size());result.put("taskCount",visible.size());result.put("completedTasks",completed.size());result.put("pendingTasks",pending.size());result.put("overdueTasks",overdue.size());result.put("delayedProjectCount",delayed.size());result.put("upcomingDeadlineCount",deadlines.size());result.put("completionRate",visible.isEmpty()?0:Math.round(completed.size()*100.0/visible.size()));result.put("byStatus",visible.stream().collect(java.util.stream.Collectors.groupingBy(Task::getStatus,java.util.stream.Collectors.counting())));result.put("byPriority",visible.stream().collect(java.util.stream.Collectors.groupingBy(Task::getPriority,java.util.stream.Collectors.counting())));result.put("byProjectStatus",visibleProjects.stream().collect(java.util.stream.Collectors.groupingBy(Project::getStatus,java.util.stream.Collectors.counting())));result.put("projectProgress",progress);result.put("delayedProjects",delayed.stream().map(p->Map.<String,Object>of("id",p.getId(),"name",p.getName(),"status",p.getStatus(),"dueDate",p.getDueDate().toString())).toList());result.put("upcomingDeadlines",deadlines);result.put("employeeWorkload",admin?users.findByCompanyIdAndMembershipStatusOrderByCreatedAtDesc(companyId,MembershipStatus.ACTIVE).stream().map(member->{List<Task> mt=visible.stream().filter(t->t.getAssignee()!=null&&t.getAssignee().getId().equals(member.getId())).toList();long done=mt.stream().filter(t->"DONE".equalsIgnoreCase(t.getStatus())).count();long late=mt.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(today)&&!"DONE".equalsIgnoreCase(t.getStatus())).count();return Map.<String,Object>of("userId",member.getId(),"name",member.getName(),"taskCount",mt.size(),"completedTasks",done,"pendingTasks",mt.size()-done,"overdueTasks",late);}).toList():List.of());return result;}
 @Transactional(readOnly=true) public List<Map<String,Object>> activity(String email){return activities.findTop20ByActorEmailOrderByCreatedAtDesc(email).stream().map(this::activityView).toList();}
 @Transactional(readOnly=true) public Map<String,Object> companyOverview(String email){User u=user(email);adminOnly(u);List<Project> active=projects.findActiveByCompanyId(u.getCompany().getId());List<Task> allTasks=tasks.findAll().stream().filter(t->t.getProject().getCompany().getId().equals(u.getCompany().getId())).toList();return Map.of("users",users.findByCompanyIdAndMembershipStatusOrderByCreatedAtDesc(u.getCompany().getId(),MembershipStatus.ACTIVE).size(),"projects",active.size(),"tasks",allTasks.size(),"completedTasks",allTasks.stream().filter(t->"DONE".equals(t.getStatus())).count(),"overdueTasks",allTasks.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(LocalDate.now())&&!"DONE".equals(t.getStatus())).count(),"unreadNotifications",notifications.countByReadFalse(),"recentActivity",activities.findTop20ByOrderByCreatedAtDesc().stream().filter(a->a.getActor()!=null&&a.getActor().getCompany()!=null&&a.getActor().getCompany().getId().equals(u.getCompany().getId())).map(this::activityView).toList(),"tasksByStatus",allTasks.stream().collect(java.util.stream.Collectors.groupingBy(Task::getStatus,java.util.stream.Collectors.counting())),"projectsByStatus",active.stream().collect(java.util.stream.Collectors.groupingBy(Project::getStatus,java.util.stream.Collectors.counting())));}
 @Transactional(readOnly=true) public List<Map<String,Object>> companyActivity(String email){User u=user(email);adminOnly(u);return activities.findTop20ByOrderByCreatedAtDesc().stream().filter(a->a.getActor()!=null&&a.getActor().getCompany()!=null&&a.getActor().getCompany().getId().equals(u.getCompany().getId())).map(this::activityView).toList();}
 @Transactional(readOnly=true) public List<Map<String,Object>> companyTasks(String email){User u=user(email);adminOnly(u);return tasks.findAll().stream().filter(t->t.getProject().getCompany().getId().equals(u.getCompany().getId())).map(this::taskView).toList();}
 private Map<String,Object> projectView(Project p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("name",p.getName());m.put("description",Objects.toString(p.getDescription(),""));m.put("status",p.getStatus());m.put("archived",p.isArchived());m.put("owner",p.getOwner().getName());m.put("dueDate",p.getDueDate()==null?"":p.getDueDate().toString());m.put("memberCount",p.getMembers().size());m.put("memberIds",p.getMembers().stream().map(User::getId).toList());m.put("memberNames",p.getMembers().stream().map(User::getName).toList());m.put("createdAt",p.getCreatedAt());return m;} private Map<String,Object> taskView(Task t){Map<String,Object> m=new LinkedHashMap<>();m.put("id",t.getId());m.put("projectId",t.getProject().getId());m.put("projectName",t.getProject().getName());m.put("title",t.getTitle());m.put("description",Objects.toString(t.getDescription(),""));m.put("status",t.getStatus());m.put("priority",t.getPriority());m.put("assignee",t.getAssignee()==null?null:t.getAssignee().getName());m.put("assigneeId",t.getAssignee()==null?null:t.getAssignee().getId());m.put("dueDate",t.getDueDate());m.put("createdAt",t.getCreatedAt());return m;} private Map<String,Object> activityView(ActivityLog a){return Map.of("id",a.getId(),"action",a.getAction(),"entityType",a.getEntityType(),"summary",a.getSummary(),"actor",a.getActor()==null?"System":a.getActor().getName(),"createdAt",a.getCreatedAt());}}
